
package com.store.productservice.entity;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="products")
public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank(message="Le nom est obligatoire") @Column(nullable=false) private String nom; @NotNull(message="Le prix est obligatoire") @DecimalMin(value="0.0", inclusive=true, message="Le prix doit être >= 0") @Column(nullable=false) private BigDecimal prix; @NotNull(message="La quantité est obligatoire") @Min(value=0, message="La quantité doit être >= 0") @Column(nullable=false) private Integer quantite; @NotNull(message="La date de création est obligatoire") @PastOrPresent(message="La date de création ne peut pas être dans le futur") @Column(name="date_creation", nullable=false) private LocalDateTime dateCreation; public Product(){} public Product(String nom, BigDecimal prix, Integer quantite, LocalDateTime dateCreation){this.nom=nom;this.prix=prix;this.quantite=quantite;this.dateCreation=dateCreation;} public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getNom(){return nom;} public void setNom(String nom){this.nom=nom;} public BigDecimal getPrix(){return prix;} public void setPrix(BigDecimal prix){this.prix=prix;} public Integer getQuantite(){return quantite;} public void setQuantite(Integer quantite){this.quantite=quantite;} public LocalDateTime getDateCreation(){return dateCreation;} public void setDateCreation(LocalDateTime dateCreation){this.dateCreation=dateCreation;} }
